from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum


class CheckKind(Enum):
    """The kinds of supply-chain checks performed for a package change."""

    CI_UPLOAD = "ci_upload"
    RELEASE_PIPELINE = "release_pipeline"
    REPO_PUBLIC = "repo_public"
    PR_LINK = "pr_link"


class CheckStatus(Enum):
    """The outcome of a single check."""

    PASS = "pass"
    WARN = "warn"
    FAIL = "fail"
    NEEDS_AGENT = "needs_agent"


# Order in which check kinds are rendered and aggregated.
CHECK_ORDER: tuple[CheckKind, ...] = (
    CheckKind.CI_UPLOAD,
    CheckKind.RELEASE_PIPELINE,
    CheckKind.REPO_PUBLIC,
    CheckKind.PR_LINK,
)

# Priority used when aggregating several statuses into one (most severe first).
_STATUS_PRIORITY: tuple[CheckStatus, ...] = (
    CheckStatus.FAIL,
    CheckStatus.NEEDS_AGENT,
    CheckStatus.WARN,
    CheckStatus.PASS,
)


@dataclass
class CheckResult:
    """The result of a single check."""

    status: CheckStatus
    details: str


@dataclass
class PackageChange:
    """A single package version change detected in a diff."""

    name: str
    old_version: str | None
    new_version: str
    checks: dict[CheckKind, CheckResult] = field(default_factory=dict)
    repo_url: str | None = None

    @property
    def needs_agent(self) -> bool:
        """Return True if at least one check needs agent attention."""
        return any(
            result.status is CheckStatus.NEEDS_AGENT for result in self.checks.values()
        )

    def to_dict(self) -> dict:
        """Return a JSON-serializable representation of this package change."""
        return {
            "name": self.name,
            "old_version": self.old_version,
            "new_version": self.new_version,
            "repo_url": self.repo_url,
            "needs_agent": self.needs_agent,
            "checks": {
                kind.value: {
                    "status": result.status.value,
                    "details": result.details,
                }
                for kind, result in self.checks.items()
            },
        }


def _aggregate_status(statuses: list[CheckStatus]) -> str:
    """Aggregate several statuses into a single serialized status string."""
    if not statuses:
        return "skipped"
    for status in _STATUS_PRIORITY:
        if status in statuses:
            return status.value
    return "skipped"


@dataclass
class CheckRunResult:
    """The result of running all checks for a PR."""

    pr_number: int
    packages: list[PackageChange] = field(default_factory=list)

    @property
    def needs_agent(self) -> bool:
        """Return True if any contained package needs agent attention."""
        return any(package.needs_agent for package in self.packages)

    def to_dict(self) -> dict:
        """Return a JSON-serializable representation of the run result."""
        # Imported lazily to avoid a circular import with the render module.
        from .render import render_comment

        checks_summary = {
            kind.value: _aggregate_status(
                [
                    package.checks[kind].status
                    for package in self.packages
                    if kind in package.checks
                ]
            )
            for kind in CHECK_ORDER
        }

        result: dict = {
            "pr_number": self.pr_number,
            "needs_agent": self.needs_agent,
            "rendered_comment": render_comment(self),
            "checks": checks_summary,
            "packages": [package.to_dict() for package in self.packages],
        }
        # Also expose each check kind at the top level (e.g. "repo_public").
        for kind in CHECK_ORDER:
            result[kind.value] = checks_summary[kind.value]
        return result
