from __future__ import annotations

import fnmatch
import re

from .models import PackageChange

# Matches a requirement specifier such as ``foo[extra]==1.2.3``.
_REQUIREMENT_RE = re.compile(
    r"^\s*([A-Za-z0-9][A-Za-z0-9._-]*)\s*(?:\[[^\]]*\])?\s*"
    r"(?:==|~=|>=|<=|!=|===|>|<)\s*([^\s;]+)"
)


def _canonicalize(name: str) -> str:
    """Normalize a package name per PEP 503."""
    return re.sub(r"[-_.]+", "-", name).lower()


def _is_tracked(path: str) -> bool:
    """Return True if the file path is a tracked requirements file."""
    for prefix in ("a/", "b/"):
        if path.startswith(prefix):
            path = path[len(prefix) :]
            break
    basename = path.rsplit("/", 1)[-1]
    return fnmatch.fnmatch(basename, "requirements*.txt")


def _parse_requirement(content: str) -> tuple[str, str] | None:
    """Parse a requirement line into a normalized (name, version) tuple."""
    # Strip inline comments and surrounding whitespace.
    content = content.split("#", 1)[0].strip()
    if not content:
        return None
    match = _REQUIREMENT_RE.match(content)
    if not match:
        return None
    return _canonicalize(match.group(1)), match.group(2).strip()


def parse_diff(diff_text: str) -> list[PackageChange]:
    """Parse a unified diff and return the package version changes it contains.

    Only files matching ``requirements*.txt`` are considered. Package names are
    normalized per PEP 503. Lines whose version does not change, comment lines,
    and inline comments are ignored.
    """
    changes: list[PackageChange] = []
    tracked = False
    removed: dict[str, str] = {}
    added: dict[str, str] = {}

    def flush() -> None:
        for name, new_version in added.items():
            old_version = removed.get(name)
            if old_version == new_version:
                # No version change for this package.
                continue
            changes.append(
                PackageChange(
                    name=name,
                    old_version=old_version,
                    new_version=new_version,
                )
            )
        removed.clear()
        added.clear()

    for raw in diff_text.splitlines():
        if raw.startswith("+++ "):
            flush()
            path = raw[4:].split("\t", 1)[0].strip()
            tracked = _is_tracked(path)
            continue
        if raw.startswith(
            ("--- ", "diff --git", "@@", "index ", "new file", "deleted file", "rename ")
        ):
            continue
        if not tracked:
            continue
        if raw.startswith("+"):
            parsed = _parse_requirement(raw[1:])
            if parsed:
                added[parsed[0]] = parsed[1]
        elif raw.startswith("-"):
            parsed = _parse_requirement(raw[1:])
            if parsed:
                removed[parsed[0]] = parsed[1]

    flush()
    return changes
