    """Strip backtick and newline characters from a string."""
    if value is None:
        return None
    return value.replace("`", "").replace("\n", "").replace("\r", "")


def _fetch_json(url: str) -> tuple[bool, int | None, dict | None]:
    """Fetch a URL and parse JSON.

    Returns a ``(ok, status_code, data)`` tuple. ``ok`` is True only for a 2xx
    response with valid JSON. ``status_code`` is None on a network error.
    """
    try:
        response = requests.get(url, timeout=_TIMEOUT)
    except requests.RequestException:
        return (False, None, None)

    status = response.status_code
    if status >= 400:
        return (False, status, None)
    try:
        return (True, status, response.json())
    except ValueError:
        return (False, status, None)


def _is_known_host_url(value: object) -> bool:
    """Return True if ``value`` is a URL hosted on a known code host."""
    if not isinstance(value, str):
        return False
    try:
        hostname = urlparse(value).hostname
    except ValueError:
        return False
    return (hostname or "").lower() in _KNOWN_HOSTS


def _select_repo_url(project_urls: dict) -> str | None:
    """Select a repository URL from the project URLs mapping."""
    # Prefer the canonical keys when they point at a known code host.
    for key in ("Source", "Repository"):
        value = project_urls.get(key)
        if _is_known_host_url(value):
            return _strip_bad_chars(value)
    # Otherwise scan every value for a known code host URL.
    for value in project_urls.values():
        if _is_known_host_url(value):
            return _strip_bad_chars(value)
    return None


def _build_provenance_urls(name: str, version: str, urls: list) -> list[str]:
    """Build the integrity/provenance URL list from the first uploaded file."""
    if not urls:
        return []
    filename = urls[0].get("filename")
    if not filename:
        return []
    return [
        f"https://pypi.org/integrity/{name}/{version}/{filename}/provenance"
    ]


