                detail = (
                    f"PEP 740 provenance attestation present from unrecognized "
                    f"publisher '{kind}'."
                )
            return ProvenanceResult(
                has_attestation=True,
                publisher_kind=kind,
                recognized_publisher=recognized,
                detail=detail,
            )

        # A response was returned but no usable publisher kind was found.
        return ProvenanceResult(
            has_attestation=False,
            publisher_kind=None,
            recognized_publisher=False,
            detail="Provenance attestation present but could not be parsed.",
        )

    return ProvenanceResult(
        has_attestation=False,
        publisher_kind=None,
        recognized_publisher=False,
        detail="No PEP 740 provenance attestation present",
    )
