from __future__ import annotations

from .models import (
    CHECK_ORDER,
    CheckKind,
    CheckRunResult,
    CheckStatus,
    PackageChange,
)

MARKER = "<!-- requirements-check -->"

_STATUS_ICON = {
    CheckStatus.PASS: "✅",
    CheckStatus.WARN: "⚠️",
    CheckStatus.FAIL: "❌",
}


def _package_label(package: PackageChange) -> str:
    """Return a human-readable label for a package change."""
    old = package.old_version if package.old_version is not None else "new"
    return f"{package.name} ({old} → {package.new_version})"


def _cell(package: PackageChange, kind: CheckKind) -> str:
    """Return the table cell content for a package/check kind combination."""
    result = package.checks.get(kind)
    if result is None:
        return "—"
    if result.status is CheckStatus.NEEDS_AGENT:
        return f"{{{{CHECK_CELL:{package.name}:{kind.value}}}}}"
    return _STATUS_ICON.get(result.status, "•")


def _detail_bullet(package: PackageChange, kind: CheckKind) -> str:
    """Return a detail bullet for a package/check kind combination."""
    result = package.checks.get(kind)
    if result is None:
        return f"- **{kind.value}**: — skipped."
    if result.status is CheckStatus.NEEDS_AGENT:
        return (
            f"- **{kind.value}**: "
            f"{{{{CHECK_DETAIL:{package.name}:{kind.value}}}}}"
        )
    icon = _STATUS_ICON.get(result.status, "•")
    return f"- **{kind.value}**: {icon} {result.details}"


def render_comment(result: CheckRunResult) -> str:
    """Render a formatted comment for a check run result."""
    lines: list[str] = [MARKER, ""]

    if not result.packages:
        lines.append("No tracked requirement changes detected.")
        return "\n".join(lines) + "\n"

    statuses = [
        check.status for package in result.packages for check in package.checks.values()
    ]
    needs_agent = any(status is CheckStatus.NEEDS_AGENT for status in statuses)
    all_pass = bool(statuses) and all(
        status is CheckStatus.PASS for status in statuses
    )

    lines.append("## Supply-chain requirements check")
    lines.append("")
    if all_pass:
        lines.append("All requirements checks passed. ✅")
    else:
        lines.append(
            f"Reviewed {len(result.packages)} package change(s); "
            "see details below."
        )
    lines.append("")

    # Collapsed when everything passes, expanded otherwise.
    lines.append("<details open>" if not all_pass else "<details>")
    lines.append("<summary>Check details</summary>")
    lines.append("")

    header = "| Package | " + " | ".join(kind.value for kind in CHECK_ORDER) + " |"
    separator = "| --- " * (len(CHECK_ORDER) + 1) + "|"
    lines.append(header)
    lines.append(separator)
    for package in result.packages:
        cells = [_cell(package, kind) for kind in CHECK_ORDER]
        lines.append("| " + _package_label(package) + " | " + " | ".join(cells) + " |")

    lines.append("")
    for package in result.packages:
        lines.append(f"### {_package_label(package)}")
        for kind in CHECK_ORDER:
            lines.append(_detail_bullet(package, kind))
        lines.append("")

    lines.append("</details>")
    return "\n".join(lines) + "\n"
