def _checks_for_not_found(package: PackageChange) -> dict[CheckKind, CheckResult]:
    """Return the check results for a package version missing from PyPI."""
    reason = (
        f"{package.name} {package.new_version} was not found on PyPI."
    )
    return {
        CheckKind.CI_UPLOAD: CheckResult(CheckStatus.FAIL, reason),
        CheckKind.RELEASE_PIPELINE: CheckResult(
            CheckStatus.FAIL,
            "Cannot verify the release pipeline; version not found on PyPI.",
        ),
        CheckKind.REPO_PUBLIC: CheckResult(
            CheckStatus.FAIL,
            "Cannot verify the repository; version not found on PyPI.",
        ),
        CheckKind.PR_LINK: CheckResult(
            CheckStatus.FAIL,
            "Cannot locate a release PR; version not found on PyPI.",
        ),
    }


def run_checks(pr_number: int, diff_text: str) -> CheckRunResult:
    """Parse a diff, fetch PyPI info, and run all checks for each package."""
    packages = parse_diff(diff_text)

    for package in packages:
        info = fetch_package_info(package.name, package.new_version)
        package.repo_url = info.repo_url

        if not info.found:
            package.checks = _checks_for_not_found(package)
            continue

        provenance = check_provenance(info)

        if provenance.has_attestation and provenance.recognized_publisher:
            package.checks[CheckKind.CI_UPLOAD] = CheckResult(
                CheckStatus.PASS,
                f"Uploaded with a PEP 740 attestation from '{provenance.publisher_kind}'.",
            )
            package.checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
                CheckStatus.PASS,
                f"Release pipeline attested by recognized publisher "
                f"'{provenance.publisher_kind}'.",
            )
        elif provenance.has_attestation and not provenance.recognized_publisher:
            package.checks[CheckKind.CI_UPLOAD] = CheckResult(
                CheckStatus.WARN,
                "An attestation is present but the publisher is unrecognised: "
                f"'{provenance.publisher_kind}'.",
            )
            package.checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
                CheckStatus.NEEDS_AGENT,
                "Release pipeline publisher unrecognised "
                f"('{provenance.publisher_kind}'); manual review required.",
            )
        else:
            package.checks[CheckKind.CI_UPLOAD] = CheckResult(
                CheckStatus.WARN,
                f"No PEP 740 provenance attestation present. {provenance.detail}",
            )
            package.checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
                CheckStatus.NEEDS_AGENT,
                "No attestation; the release pipeline must be verified manually.",
            )

        if info.repo_url is None:
            package.checks[CheckKind.REPO_PUBLIC] = CheckResult(
                CheckStatus.FAIL,
                f"{package.name} does not advertise a source repository on a "
                "known code host.",
            )
            package.checks[CheckKind.PR_LINK] = CheckResult(
                CheckStatus.FAIL,
                "No repository URL is available to locate a release PR.",
            )
        else:
            package.checks[CheckKind.REPO_PUBLIC] = CheckResult(
                CheckStatus.NEEDS_AGENT,
                f"Verify that {info.repo_url} is a public repository.",
            )
            package.checks[CheckKind.PR_LINK] = CheckResult(
                CheckStatus.NEEDS_AGENT,
                f"Locate the release PR for {package.new_version} in {info.repo_url}.",
            )

    return CheckRunResult(pr_number=pr_number, packages=packages)
